cd /work/output/artifacts/skill-flow-ipe-query-params/QueryParamsTest/QueryParamsTest \
  && uip maestro flow node configure "QueryParamsTest.flow" "listAllTasksInclHidden1" \
    --detail '{
      "authentication": "manual",
      "method": "GET",
      "url": "https://tasks.googleapis.com/tasks/v1/lists/@default/tasks",
      "query": {
        "showHidden": "true",
        "showCompleted": "true"
      },
      "headers": {
        "Authorization": "=js:`Bearer ${$vars.start.output.accessToken}`"
      }
    }' --output json \
  && uip maestro flow validate "QueryParamsTest.flow" --output json \
  && uip maestro flow format "QueryParamsTest.flow" --output json 2>&1

